"""Imports every SourceAssets/Audio/*.wav as a sound wave /Game/Audio/SW_<Name> (generated by Tools/Audio/gen_sounds.py).

Run: Scripts/uepy.sh Tools/UE/import_sounds.py   (the editor must not be running)
Prints `DIA_OK /Game/Audio/SW_<Name> <seconds> <looping>` per sound; on error prints `DIA_FAIL ...` and exits non-zero.

A file whose name ends in _loop becomes a looping wave. Idempotent: an existing wave is replaced in place.
"""
import glob
import os
import sys
import traceback

import unreal

AUDIO_DIR = "/Game/Audio"


def main():
    root = unreal.Paths.project_dir()
    files = sorted(glob.glob(os.path.join(root, "SourceAssets", "Audio", "*.wav")))
    if not files:
        raise RuntimeError("no .wav files in SourceAssets/Audio")

    tasks = []
    for path in files:
        name = os.path.splitext(os.path.basename(path))[0]
        task = unreal.AssetImportTask()
        task.set_editor_property("filename", path)
        task.set_editor_property("destination_path", AUDIO_DIR)
        task.set_editor_property("destination_name", "SW_" + name)
        task.set_editor_property("automated", True)
        task.set_editor_property("replace_existing", True)
        task.set_editor_property("replace_existing_settings", True)
        task.set_editor_property("save", True)
        task.set_editor_property("factory", unreal.SoundFactory())
        tasks.append(task)
    unreal.AssetToolsHelpers.get_asset_tools().import_asset_tasks(tasks)

    failed = False
    for path in files:
        name = os.path.splitext(os.path.basename(path))[0]
        asset_path = "%s/SW_%s" % (AUDIO_DIR, name)
        wave = unreal.EditorAssetLibrary.load_asset(asset_path)
        if wave is None:
            print("DIA_FAIL missing %s" % asset_path)
            failed = True
            continue
        looping = name.endswith("_loop")
        wave.set_editor_property("looping", looping)
        unreal.EditorAssetLibrary.save_asset(asset_path)
        print("DIA_OK %s %.2f %s" % (asset_path, wave.get_editor_property("duration"), looping))
    if failed:
        sys.exit(1)


try:
    main()
except Exception:
    traceback.print_exc()
    print("DIA_FAIL exception")
    sys.exit(1)
